import React, { useMemo } from 'react';
import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";
import { Clock, MapPin, ChevronRight, AlertCircle, CheckCircle2 } from 'lucide-react';

const cn = (...inputs) => twMerge(clsx(inputs));

export default function CalendarListView({
    currentDate,
    bookings = {}, // Map of bookingId -> Booking
    slots = [],    // Array of active slots
    onBookingClick
}) {
    // Generate 7 days range
    const days = useMemo(() => {
        const d = new Date(currentDate);
        const range = [];
        for (let i = 0; i < 7; i++) {
            range.push(new Date(d));
            d.setDate(d.getDate() + 1);
        }
        return range;
    }, [currentDate]);

    // Group Bookings by Date (YYYY-MM-DD)
    const bookingsByDate = useMemo(() => {
        const map = {}; // "2024-01-01": [BookingObjects]

        // 1. Identify relevant bookings for the 7-day range
        // Just need strings for range comparison if we have YYYY-MM-DD
        const startStr = days[0].toLocaleDateString("en-CA");
        const endStr = days[6].toLocaleDateString("en-CA");

        const bookingDates = {}; // bookingId -> Set<dateStr>

        slots.forEach(slot => {
            // slot.date should be "YYYY-MM-DD"
            if (slot.date >= startStr && slot.date <= endStr) {
                // Filter out Open Play Blocks
                const booking = bookings[slot.bookingId];
                if (booking && booking.type === "OPEN_PLAY_BLOCK") return;

                if (!bookingDates[slot.bookingId]) bookingDates[slot.bookingId] = new Set();
                bookingDates[slot.bookingId].add(slot.date);
            }
        });

        // Now populate the map
        Object.entries(bookingDates).forEach(([bId, dateSet]) => {
            const booking = bookings[bId];
            if (booking) {
                dateSet.forEach(dateStr => {
                    if (!map[dateStr]) map[dateStr] = [];
                    map[dateStr].push(booking);
                });
            }
        });

        return map;
    }, [bookings, slots, days]);

    // Helper to format minutes to HH:MM AM/PM
    const formatTime = (totalMinutes) => {
        const h = Math.floor(totalMinutes / 60);
        const m = totalMinutes % 60;
        const d = new Date();
        d.setHours(h, m, 0, 0);
        return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
    };

    // Helper to get summary of a booking for a specific date
    const getBookingSummary = (booking, dateStr) => {
        // Find slots for this booking on this date
        const bookingSlots = booking.slotIds
            .map(id => slots.find(s => s.slotId === id))
            .filter(Boolean)
            // Match using explicit date field
            .filter(s => s.date === dateStr);

        if (bookingSlots.length === 0) return null;

        // Sort by integer startTime
        bookingSlots.sort((a, b) => a.startTime - b.startTime);

        const firstSlot = bookingSlots[0];
        const lastSlot = bookingSlots[bookingSlots.length - 1];

        // Ensure start/end are integers
        const startMins = Number(firstSlot.startTime);
        const endMins = Number(lastSlot.endTime);

        // Court list
        const courts = [...new Set(bookingSlots.map(s => s.courtId))].sort((a, b) => a - b);

        return {
            timeRange: `${formatTime(startMins)} - ${formatTime(endMins)}`,
            courtLabel: courts.length === 1 ? `Court ${courts[0]}` : `Courts ${courts.join(', ')}`,
            slotCount: bookingSlots.length
        };
    };

    return (
        <div className="flex flex-col h-full bg-slate-50 p-4 lg:p-6 overflow-y-auto">
            <div className="max-w-3xl mx-auto w-full space-y-8 pb-10">
                {days.map(day => {
                    const dateStr = day.toLocaleDateString("en-CA");
                    const dayBookings = bookingsByDate[dateStr] || [];
                    const isToday = new Date().toLocaleDateString("en-CA") === dateStr;

                    return (
                        <div key={dateStr} className="space-y-3">
                            {/* Day Header */}
                            <div className="flex items-baseline gap-3 border-b border-slate-200 pb-2">
                                <h3 className={cn(
                                    "text-lg font-bold",
                                    isToday ? "text-slate-900" : "text-slate-700"
                                )}>
                                    {day.toLocaleDateString('en-US', { weekday: 'long' })}
                                </h3>
                                <span className="text-sm font-medium text-slate-400">
                                    {day.toLocaleDateString('en-US', { month: 'long', day: 'numeric' })}
                                </span>
                            </div>

                            {/* Bookings List */}
                            {dayBookings.length === 0 ? (
                                <div className="text-xs text-slate-400 font-medium italic pl-1">
                                    No bookings scheduled
                                </div>
                            ) : (
                                <div className="space-y-3">
                                    {dayBookings.map(booking => {
                                        const summary = getBookingSummary(booking, dateStr);
                                        if (!summary) return null;

                                        const isBlock = booking.type === "OPEN_PLAY_BLOCK";
                                        // Use paymentSummary.totalAmount as authoritative total (respects discounts).
                                        // Fall back to raw slot sum only if paymentSummary is missing/zero.
                                        const allBookingSlots = slots.filter(s => s.bookingId === booking.id);
                                        const rawSlotTotal = allBookingSlots.reduce((sum, s) => sum + (s.price || 0), 0);

                                        const pSum = booking.paymentSummary || {};
                                        const effectiveTotal = (pSum.totalAmount !== undefined && pSum.totalAmount !== null)
                                            ? pSum.totalAmount
                                            : rawSlotTotal;

                                        const isPaid = (pSum.amountPaid || 0) >= effectiveTotal && effectiveTotal > 0;
                                        const isPartial = !isPaid && (pSum.amountPaid || 0) > 0;
                                        const status = isPaid ? "PAID" : (isPartial ? "PARTIAL" : "UNPAID");

                                        return (
                                            <div
                                                key={booking.id}
                                                onClick={() => onBookingClick(booking.id)}
                                                className={cn(
                                                    "group relative bg-white rounded-lg border shadow-sm p-4 hover:shadow-md transition-all cursor-pointer flex flex-col sm:flex-row gap-4 sm:items-center",
                                                    isBlock ? "border-slate-200 bg-slate-50/50" :
                                                        status === "PAID" ? "border-emerald-100 hover:border-emerald-300" :
                                                            status === "PARTIAL" ? "border-yellow-200 hover:border-yellow-300" :
                                                                "border-red-200 hover:border-red-300" // Unpaid = Red
                                                )}
                                            >
                                                {/* Status Strip */}
                                                <div className={cn(
                                                    "absolute left-0 top-0 bottom-0 w-1 rounded-l-lg",
                                                    isBlock ? "bg-slate-300" :
                                                        status === "PAID" ? "bg-emerald-500" :
                                                            status === "PARTIAL" ? "bg-yellow-400" :
                                                                "bg-red-500" // Unpaid = Red
                                                )} />

                                                {/* Left: Time & Courts */}
                                                <div className="min-w-[140px]">
                                                    <div className="flex items-center gap-2 text-slate-900 font-semibold">
                                                        <Clock className="h-4 w-4 text-slate-400" />
                                                        {summary.timeRange}
                                                    </div>
                                                    <div className="flex items-center gap-2 text-xs font-medium text-slate-500 mt-1">
                                                        <MapPin className="h-3.5 w-3.5" />
                                                        {summary.courtLabel}
                                                    </div>
                                                </div>

                                                {/* Center: Renter Info */}
                                                <div className="flex-1">
                                                    {isBlock ? (
                                                        <span className="text-sm font-semibold text-slate-500 italic">
                                                            Open Play Block / Unavailable
                                                        </span>
                                                    ) : (
                                                        <div>
                                                            <div className="text-sm font-bold text-slate-800 flex items-center gap-2">
                                                                {booking.renter?.name || "Unknown Renter"}
                                                                {booking.renter?.discount > 0 && (
                                                                    <span className="text-[9px] font-bold bg-emerald-100 text-emerald-700 border border-emerald-200 px-1.5 py-0.5 rounded-full">
                                                                        {booking.renter.discount}% off
                                                                    </span>
                                                                )}
                                                            </div>
                                                            {booking.renter?.contact && (
                                                                <div className="text-xs text-slate-500 mt-0.5">
                                                                    {booking.renter.contact}
                                                                </div>
                                                            )}
                                                        </div>
                                                    )}
                                                </div>

                                                {/* Right: Payment & Action */}
                                                <div className="flex items-center justify-between sm:justify-end gap-4 min-w-[120px]">
                                                    {!isBlock && (
                                                        <div className="text-right">
                                                            <div className={cn(
                                                                "inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider",
                                                                status === "PAID" ? "bg-emerald-100 text-emerald-700" :
                                                                    status === "PARTIAL" ? "bg-yellow-100 text-yellow-700" :
                                                                        "bg-red-100 text-red-700"
                                                            )}>
                                                                {status === "PAID" && <CheckCircle2 className="h-3 w-3" />}
                                                                {status === "PARTIAL" && <AlertCircle className="h-3 w-3" />}
                                                                {status}
                                                            </div>
                                                            <div className="text-xs font-semibold text-slate-900 mt-1">
                                                                PHP {effectiveTotal.toLocaleString()}
                                                                {booking.renter?.discount > 0 && rawSlotTotal > effectiveTotal && (
                                                                    <span className="ml-1 text-[10px] text-slate-400 line-through font-normal">
                                                                        {rawSlotTotal.toLocaleString()}
                                                                    </span>
                                                                )}
                                                            </div>
                                                        </div>
                                                    )}
                                                    <ChevronRight className="h-4 w-4 text-slate-300 group-hover:text-slate-600 transition-colors" />
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    );
}
